"use client";

import { useState } from "react";
import { logout } from "@/services/auth"; // Pastikan Anda memiliki fungsi logout di services

export default function Navbar({ userProfile }: { userProfile: any }) {
  const [showDropdown, setShowDropdown] = useState(false);

  return (
    <nav className="h-16 bg-white border-b border-slate-200 flex items-center justify-between px-6 sticky top-0 z-50">
      {/* Bagian Kiri: Search Bar */}
      <div className="flex-1 max-w-md hidden md:block">
        <div className="relative group">
          <span className="absolute inset-y-0 left-0 pl-3 flex items-center text-slate-400">
            🔍
          </span>
          <input
            type="text"
            placeholder="Cari data pasien atau RM..."
            className="block w-full pl-10 pr-3 py-2 border border-slate-200 rounded-xl bg-slate-50 text-sm placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:bg-white transition-all"
          />
        </div>
      </div>

      {/* Bagian Kanan: User Profile & Notifikasi */}
      <div className="flex items-center gap-4">
        {/* Ikon Notifikasi (Visual Only) */}
        <button className="p-2 text-slate-500 hover:bg-slate-100 rounded-full relative">
          🔔
          <span className="absolute top-2 right-2 w-2 h-2 bg-red-500 rounded-full border-2 border-white"></span>
        </button>

        {/* User Profile Dropdown */}
        <div className="relative">
          <button 
            onClick={() => setShowDropdown(!showDropdown)}
            className="flex items-center gap-3 p-1 pl-3 hover:bg-slate-50 rounded-xl transition-all border border-transparent hover:border-slate-100"
          >
            <div className="text-right hidden sm:block">
              <p className="text-xs font-bold text-slate-800 leading-tight">
                {userProfile?.full_name || "Petugas RS Arun"}
              </p>
              <p className="text-[10px] text-slate-500 font-medium uppercase tracking-tighter">
                {userProfile?.role}
              </p>
            </div>
            {/* Avatar Placeholder */}
            <div className="w-9 h-9 bg-gradient-to-tr from-blue-600 to-indigo-500 rounded-lg flex items-center justify-center text-white font-bold shadow-sm">
              {(userProfile?.full_name?.[0] || "P").toUpperCase()}
            </div>
          </button>

          {/* Dropdown Menu */}
          {showDropdown && (
            <div className="absolute right-0 mt-2 w-48 bg-white border border-slate-100 rounded-xl shadow-xl py-2 z-50 animate-in fade-in zoom-in duration-200">
              <div className="px-4 py-2 border-b border-slate-50 mb-1">
                <p className="text-xs text-slate-400">Pilihan Menu</p>
              </div>
              <button className="w-full text-left px-4 py-2 text-sm text-slate-700 hover:bg-slate-50 flex items-center gap-2">
                👤 Profil Saya
              </button>
              <button className="w-full text-left px-4 py-2 text-sm text-slate-700 hover:bg-slate-50 flex items-center gap-2">
                ⚙️ Pengaturan
              </button>
              <hr className="my-1 border-slate-50" />
              <button 
                onClick={() => logout()}
                className="w-full text-left px-4 py-2 text-sm text-red-600 hover:bg-red-50 flex items-center gap-2 font-medium"
              >
                🚪 Keluar Sistem
              </button>
            </div>
          )}
        </div>
      </div>
    </nav>
  );
}