"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";

// Definisi menu berdasarkan Role
const menuByRole = {
  Perawat: [
    { name: "Dashboard", href: "/dashboard/perawat", icon: "📊" },
    { name: "Form Surveilans", href: "/dashboard/perawat/form", icon: "📝" },
  ],
  "Admin PPI": [
    { name: "Analitik HAIs", href: "/dashboard/admin/analytics", icon: "📈" },
    { name: "Semua Laporan", href: "/dashboard/admin/reports", icon: "📁" },
    { name: "Master Ruangan", href: "/dashboard/admin/rooms", icon: "🏥" },
  ],
  Manager: [
    { name: "Ringkasan Eksekutif", href: "/dashboard/manager/summary", icon: "🏢" },
  ],
};

export default function Sidebar({ role }: { role: string }) {
  const pathname = usePathname();
  const menus = menuByRole[role as keyof typeof menuByRole] || [];

  return (
    <aside className="w-64 bg-white border-r min-h-screen hidden md:block shadow-sm">
      <div className="p-6">
        <h1 className="text-xl font-bold text-blue-700">RS ARUN PPI</h1>
        <p className="text-[10px] text-slate-400">LHOKSEUMAWE</p>
      </div>
      <nav className="mt-4 px-4 space-y-2">
        {menus.map((item) => (
          <Link
            key={item.href}
            href={item.href}
            className={`flex items-center gap-3 px-4 py-3 rounded-lg text-sm font-medium transition-all ${
              pathname === item.href 
                ? "bg-blue-50 text-blue-600 shadow-sm" 
                : "text-slate-600 hover:bg-slate-50"
            }`}
          >
            <span>{item.icon}</span>
            {item.name}
          </Link>
        ))}
      </nav>
    </aside>
  );
}